-- Minimal DDL for testing — only creates the tables used by e2e/security tests.
-- MD_MATERIAL is the primary table used for masking assertions.
CREATE TABLE IF NOT EXISTS MD_MATERIAL (
  ID VARCHAR(255) NOT NULL,
  MATERIAL_CODE VARCHAR(255) NULL DEFAULT NULL,
  MATERIAL_NAME VARCHAR(255) NULL DEFAULT NULL,
  PLAN_PRICE VARCHAR(255) NULL DEFAULT NULL,
  MATERIAL_TYPE VARCHAR(255) NULL DEFAULT NULL,
  STATUS VARCHAR(255) NULL DEFAULT NULL,
  DEL_FLAG VARCHAR(255) NULL DEFAULT NULL,
  CREATE_BY VARCHAR(255) NULL DEFAULT NULL,
  CREATE_TIME VARCHAR(255) NULL DEFAULT NULL,
  UPDATE_BY VARCHAR(255) NULL DEFAULT NULL,
  UPDATE_TIME VARCHAR(255) NULL DEFAULT NULL,
  PRIMARY KEY (ID)
) ENGINE = InnoDB CHARACTER SET = utf8mb4;

CREATE TABLE IF NOT EXISTS MD_STATION (
  ID VARCHAR(255) NOT NULL,
  STATION_CODE VARCHAR(255) NULL DEFAULT NULL,
  STATION_NAME VARCHAR(255) NULL DEFAULT NULL,
  STATUS VARCHAR(255) NULL DEFAULT NULL,
  DEL_FLAG VARCHAR(255) NULL DEFAULT NULL,
  PRIMARY KEY (ID)
) ENGINE = InnoDB CHARACTER SET = utf8mb4;

CREATE TABLE IF NOT EXISTS MD_WAREHOUSE_LOCATION (
  ID VARCHAR(255) NOT NULL,
  LOCATION_CODE VARCHAR(255) NULL DEFAULT NULL,
  LOCATION_NAME VARCHAR(255) NULL DEFAULT NULL,
  STATUS VARCHAR(255) NULL DEFAULT NULL,
  DEL_FLAG VARCHAR(255) NULL DEFAULT NULL,
  PRIMARY KEY (ID)
) ENGINE = InnoDB CHARACTER SET = utf8mb4;

CREATE TABLE IF NOT EXISTS MD_MODEL (
  ID VARCHAR(255) NOT NULL,
  MODEL_CODE VARCHAR(255) NULL DEFAULT NULL,
  MODEL_NAME VARCHAR(255) NULL DEFAULT NULL,
  STATUS VARCHAR(255) NULL DEFAULT NULL,
  DEL_FLAG VARCHAR(255) NULL DEFAULT NULL,
  PRIMARY KEY (ID)
) ENGINE = InnoDB CHARACTER SET = utf8mb4;

CREATE TABLE IF NOT EXISTS MD_OPERATION (
  ID VARCHAR(255) NOT NULL,
  OPERATION_CODE VARCHAR(255) NULL DEFAULT NULL,
  OPERATION_NAME VARCHAR(255) NULL DEFAULT NULL,
  STATUS VARCHAR(255) NULL DEFAULT NULL,
  DEL_FLAG VARCHAR(255) NULL DEFAULT NULL,
  PRIMARY KEY (ID)
) ENGINE = InnoDB CHARACTER SET = utf8mb4;

CREATE TABLE IF NOT EXISTS BO_SORTING_PLAN (
  ID VARCHAR(255) NOT NULL,
  DISPATCH_NO VARCHAR(255) NULL DEFAULT NULL,
  PLAN_STATUS_B VARCHAR(255) NULL DEFAULT NULL,
  DEL_FLAG VARCHAR(255) NULL DEFAULT NULL,
  PRIMARY KEY (ID)
) ENGINE = InnoDB CHARACTER SET = utf8mb4;

CREATE TABLE IF NOT EXISTS BO_SORTING_PLAN_DETAIL (
  ID VARCHAR(255) NOT NULL,
  SORTING_PLAN_ID VARCHAR(255) NULL DEFAULT NULL,
  MATERIAL_ID VARCHAR(255) NULL DEFAULT NULL,
  PLAN_DETAIL_STATUS VARCHAR(255) NULL DEFAULT NULL,
  DEL_FLAG VARCHAR(255) NULL DEFAULT NULL,
  PRIMARY KEY (ID)
) ENGINE = InnoDB CHARACTER SET = utf8mb4;

CREATE TABLE IF NOT EXISTS BO_DELIVERY_TASK_DETAIL (
  ID VARCHAR(255) NOT NULL,
  DELIVERY_TASK_CODE VARCHAR(255) NULL DEFAULT NULL,
  DELIVERY_DETAIL_STATUS VARCHAR(255) NULL DEFAULT NULL,
  MATERIAL_CODE VARCHAR(255) NULL DEFAULT NULL,
  PLAN_AMOUNT VARCHAR(255) NULL DEFAULT NULL,
  DEL_FLAG VARCHAR(255) NULL DEFAULT NULL,
  PRIMARY KEY (ID)
) ENGINE = InnoDB CHARACTER SET = utf8mb4;

CREATE TABLE IF NOT EXISTS BW_STOCK_LEDGER (
  ID VARCHAR(255) NOT NULL,
  MATERIAL_CODE VARCHAR(255) NULL DEFAULT NULL,
  LOCATION_ID VARCHAR(255) NULL DEFAULT NULL,
  STOCK_AMOUNT VARCHAR(255) NULL DEFAULT NULL,
  DEL_FLAG VARCHAR(255) NULL DEFAULT NULL,
  PRIMARY KEY (ID)
) ENGINE = InnoDB CHARACTER SET = utf8mb4;
